export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g);
  const t = Math.min(Math.max(time, 0), 2 * T);
  const vt = u - g * t;
  const yt = u * t - g * t * t / 2;
  const held = t < T;
  const vd = held ? 0 : vt;
  const ad = held ? 0 : -g;
  const yd = held ? H : yt;
  const W = 640, Hh = 420;
  const top = 60, bot = 380;
  const Y = (m) => bot - (m / 2.2) * (bot - top);
  const tossState = t === 0 ? 'At launch' : (Math.abs(t - T) < 0.005 ? 'At the top' : (t < T ? 'Rising' : (t >= 2 * T - 1e-9 ? 'At launch height' : 'Falling')));
  const dropState = held ? 'Held in place' : (t >= 2 * T - 1e-9 ? 'At launch height' : (t - T < 0.1 ? 'Just released' : 'Falling together'));
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.toss', x: 10, y: 36, w: 305, h: 374, title: 'Toss', state: tossState, role: 'input' }));
  objs.push(...sdk.panel({ id: 'lane.drop', x: 325, y: 36, w: 305, h: 374, title: 'Drop', state: dropState, role: 'output' }));
  const cols = [[162, 'toss', yt, vt, -g], [477, 'drop', yd, vd, ad]];
  for (const [cx, n, y, v, a] of cols) {
    objs.push(sdk.circle('ball.' + n, cx, Y(y), 24));
    objs.push(...sdk.vector('vec.v.' + n, { x: cx - 30, y: Y(y) }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
    objs.push(...sdk.vector('vec.a.' + n, { x: cx + 30, y: Y(y) }, { value: a, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
    objs.push(...sdk.callout(cx + 50, Y(y) - 40, ['v ' + sdk.format(v, 2) + ' m/s', 'a ' + sdk.format(a, 1) + ' m/s^2'], { id: 'callout.' + n }));
  }
  objs.push(...sdk.gate('gate.drop', 477, Y(H) + 20, { open: !held }));
  objs.push(sdk.line('mark.toss', 100, bot + 12, 225, bot + 12));
  objs.push(sdk.line('mark.drop', 415, bot + 12, 540, bot + 12));
  return {
    frame: { width: W, height: Hh, objects: objs, readouts: [
      { id: 'tossedVelocity', value: vt }, { id: 'tossedAcceleration', value: -g },
      { id: 'dropVelocity', value: vd }, { id: 'dropAcceleration', value: ad }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vt, tossedAcceleration: -g, tossedHeight: yt, dropVelocity: vd, dropAcceleration: ad, dropHeight: yd }
  };
}
